const fs=require('fs');
const [,,srcPath,outPath]=process.argv;
if(!srcPath||!outPath) throw new Error('USAGE: node patch-hide-card-signal-count-20261004.js <src> <out>');
let s=fs.readFileSync(srcPath,'utf8');
const MARK='B46_CARD_SIGNAL_COUNT_COLLISION_FIX_20261004';
const OLD='data-signal-count="${rows.length}"';
const NEW='data-inline-signal-count="${rows.length}"';
if(s.includes(MARK)) throw new Error('CARD_SIGNAL_COUNT_FIX_ALREADY_PRESENT_STOP');
if(!s.includes('B46_STABLE_MATCH_CARD_DOM_20261004')) throw new Error('STABLE_CARD_DOM_BASE_MISSING_STOP');
if((s.split(OLD).length-1)!==1) throw new Error('CARD_SIGNAL_COUNT_ANCHOR_NOT_EXACTLY_ONE');
if(!s.includes("setText('[data-signal-count]',activeSignals)")) throw new Error('GLOBAL_SIGNAL_COUNTER_ANCHOR_MISSING');
s=s.replace('function inlineSignalsHtml(rows){',`/* ${MARK}: card-local count metadata is isolated from the global counter selector. */\nfunction inlineSignalsHtml(rows){`);
s=s.replace(OLD,NEW);
if(!s.includes(MARK)||!s.includes(NEW)) throw new Error('CARD_SIGNAL_COUNT_FIX_NOT_APPLIED');
if(s.includes(OLD)) throw new Error('CARD_SIGNAL_COUNT_COLLISION_STILL_PRESENT');
if((s.match(/data-signal-count/g)||[]).length!==1) throw new Error('UNEXPECTED_REMAINING_SIGNAL_COUNT_SELECTOR_COUNT');
if((s.match(/data-inline-signal-count/g)||[]).length!==1) throw new Error('INLINE_SIGNAL_COUNT_METADATA_COUNT_BAD');
fs.writeFileSync(outPath,s);
console.log(JSON.stringify({ok:true,marker:MARK,inputBytes:Buffer.byteLength(fs.readFileSync(srcPath)),outputBytes:Buffer.byteLength(s),fetchCountBefore:(fs.readFileSync(srcPath,'utf8').match(/\bfetch\(/g)||[]).length,fetchCountAfter:(s.match(/\bfetch\(/g)||[]).length}));
